    /// <summary>
    /// Calculates and sets the return unit price and discount for the sales line based on the original invoice line when the sales order is of type ReturnItem.
    /// </summary>
    private void metSetReturnUnitPriceAndDiscount(METSalesTable _metSalesTable)
    {
        SalesQty            quantity;
        SalesLine           salesLine, salesLineOrig;
        CustInvoiceTrans    custInvoiceTrans;

        salesLine = SalesLine::findRecId(this.RecId);
        METSalesLine metSalesLine = salesLine.metSalesLine();
        SalesId originalSalesId = _metSalesTable.ClaimSalesId ? _metSalesTable.ClaimSalesId : _metSalesTable.OriginalSalesId;

        select firstonly salesLineOrig
            join SalesId, ItemId from custInvoiceTrans
                where custInvoiceTrans.InventTransId == salesLineOrig.InventTransId
                && (!metSalesLine.InvoiceNumber || custInvoiceTrans.InvoiceId == metSalesLine.InvoiceNumber)
                && custInvoiceTrans.SalesId == originalSalesId
            && ((!metSalesLine.InvoiceLineNumber || custInvoiceTrans.LineNum == metSalesLine.InvoiceLineNumber) && custInvoiceTrans.ItemId == salesLine.ItemId);
        
        if (salesLineOrig)
        {
            real        convFactor  = 1;
            PdsCWUnitId pdsCWUnitId = this.pdsCWUnitId();

            if (!pdsCWUnitId && salesLineOrig.SalesUnit !=  this.SalesUnit)
            {
                convFactor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(this.itemId,
                                                                            this.InventDimId,
                                                                            1,
                                                                            salesLineOrig.SalesUnit,
                                                                            this.SalesUnit,
                                                                            NoYes::Yes);
            }

            if (salesLine.SalesType == SalesType::ReturnItem)
            {
                if (pdsCWUnitId)
                {
                    quantity = SalesParmLine::isCWClaimCreditApplicable(this) ? this.metSalesLine().CWReturnWeight : this.PdsCWExpectedRetQty;
                }
                else
                {
                    quantity = this.ExpectedRetQty;
                }
            }
            else
            {
                quantity = this.SalesQty;
            }
        
            this.SalesPrice    = convFactor ? salesLineOrig.SalesPrice / convFactor : salesLineOrig.SalesPrice;
            this.LineDisc      = METReturnOrderCopyChargesHelper::getLineDiscountAmount(salesLine.InventTransId);
            this.LineAmount    = this.calcLineAmount(quantity);
        }
    }

/// <summary>
/// Find corresponding METSalesLine (additional fields).
/// </summary>
/// <returns>METSalesLine record</returns>
public METSalesLine metSalesLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METSalesLine));
}

    /// <summary>
    /// pack the METSalesLine record fields
    /// </summary>
    /// <param name = "_metSalesLine">Record buffer of METSalesLine to pack</param>
    public void metPackMETSalesLine(METSalesLine _metSalesLine)
    {
        _metSalesLine.SalesLine = this.RecId;

        // Sales order Return / Claims
        if (SalesTable::find(SalesLine::findRecId(_metSalesLine.SalesLine).SalesId).SalesType == SalesType::ReturnItem
            && METInventTable::find(this.ItemId).METTariffItemCodeBaseRecid)
        {
            _metSalesLine.ContinuingPermissionNumber = SalesLine::findRecId(_metSalesLine.SalesLine).SalesId;
        }
        // Sales order Return / Claims

        this.SysExtensionSerializerMap::packExtensionTable(_metSalesLine);
    }

    protected METSalesUnit metGetDefaultOrderUnit()
    {
        InventItemSalesSetup salesSetup;
        METSalesUnit salesUnit;

        salesSetup = InventItemSalesSetup::find(this.ItemId, this.InventDimId);

        if (salesSetup)
        {
            salesUnit = salesSetup.METSalesUnit;
        }

        return salesUnit;
    }

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name = "_dropInvent">_dropInvent</param>
    /// <param name = "_findMarkup">_findMarkup</param>
    /// <param name = "_childBuffer">_childBuffer</param>
    /// <param name = "_skipCreditLimitCheck">_skipCreditLimitCheck</param>
    /// <param name = "_skipWHSProcesses">_skipWHSProcesses</param>
    /// <param name = "_interCompanyInventTransId">_interCompanyInventTransId</param>
    public void insert(boolean     _dropInvent,
                        boolean     _findMarkup,
                        Common      _childBuffer,
                        boolean     _skipCreditLimitCheck,
                        boolean     _skipWHSProcesses,
                        InventRefTransId _interCompanyInventTransId)
    {
        SalesTable      salesTable = SalesTable::find(this.SalesId);
        METSalesLine    metSalesLine;

        boolean intercompanyTransferFulfillment = false; //C - Added for the Task 122004: CB274 - Intercompany Transfers

        intercompanyTransferFulfillment = this.updateIntercompanySODetails();

        if (this.METCWActualWeight)
        {
            this.LineAmount = this.calcLineAmount(this.METCWActualWeight);
        }
        this.METSalesUnit = this.metGetDefaultOrderUnit();            
        //this.metSetReturnUnitPriceAndDiscount();

        next insert(_dropInvent, _findMarkup, _childBuffer, _skipCreditLimitCheck, _skipWHSProcesses, _interCompanyInventTransId );

        metSalesLine = this.metSalesLine();

        //NS-Added for the Task 122004: CB274 - Intercompany Transfers
        if (intercompanyTransferFulfillment == true)
        {
            metSalesLine.ExcludeFromDualWrite = NoYes::Yes;
        }
        //NE-Added for the Task 122004: CB274 - Intercompany Transfers

        // CB173 Sales Order Extract Screen V2 - refactor
        this.metSetSalesUnitFields(metsalesLine);
        this.metSetActualUnitFields(metsalesLine);
        // CB871_CB872 Sales returns . Get unit in shipcase during return order line export
        this.metSetWMSFactor(metsalesLine);

        // Sales order Return / Claims
        if (salesTable.SalesType == SalesType::ReturnItem)
        {
            this.metSetExciseDutyFields(metSalesLine);
        }
        // Sales order Return / Claims
        
        if (metSalesLine.RecId == 0)
        {
            this.metPackMETSalesLine(metSalesLine);
            this.SysExtensionSerializerMap::postInsert();
        }

        //Start-BUG-240252
        if (salesTable.METOrderExtractStatus != metSalesLine.OrderExtractStatus)
        {
            salesTable.selectForUpdate(true);
            salesTable.metUpdateExtractStatus();
        }
        //End-BUG-240252

        //NS - Added for Task 269070: CB887 - BlueYonder to D365 (Intercompany Fulfilment)
        this.updateIntercompanyPOReplenishmentReference();
        //NE - Added for Task 269070: CB887 - BlueYonder to D365 (Intercompany Fulfilment)

    }

    // <summary>
    /// Updates the intercompany sales order (SO) details based on fulfillment status from the originating company.
    /// Added for the Task 122004: CB274 - Intercompany Transfers
    /// </summary>
    /// <returns>
    /// Returns <c>true</c> if the originating intercompany sales order has been fulfilled and the current sales order's
    /// inventory dimensions are updated accordingly; otherwise, returns <c>false</c>.
    /// </returns>
    public boolean updateIntercompanySODetails()
    {
        boolean     intercompanyTransferFulfillment = false;
        SalesTable  salesTable                      = SalesTable::find(this.SalesId);

        if (salesTable.InterCompanyOrigin == InterCompanyOrigin::Derived)
        {
            changecompany (salesTable.InterCompanyCompanyId)
            {
                SalesTable origSalesTable;

                select firstonly RecId from origSalesTable
                    where origSalesTable.SalesId == salesTable.InterCompanyOriginalSalesId
                    && origSalesTable.METIntercompanyTransferFulfillment == NoYes::Yes;

                if (origSalesTable.RecId)
                {
                    intercompanyTransferFulfillment = true;
                }
            }

            if (intercompanyTransferFulfillment == true)
            {
                InventDim       inventDim = InventDim::find(this.InventDimId);
                InventDim       inventDimLoc;
                WMSLocation     wmsLocation;
                InventBatch     inventBatch;

                select firstonly wMSLocationId from wmsLocation
                    where wmsLocation.inventLocationId == inventDim.InventLocationId;

                select firstonly InventBatchId from inventBatch
                    where inventBatch.itemId == this.ItemId;
            
                inventDimLoc.InventSiteId           = inventDim.InventSiteId;
                inventDimLoc.wMSLocationId          = wmsLocation.wMSLocationId;
                inventDimLoc.InventLocationId       = inventDim.InventLocationId;
            
                if (inventBatch.InventBatchId)
                {
                    inventDimLoc.inventBatchId = inventBatch.inventBatchId;
                }

                inventDimLoc = InventDim::findOrCreate(inventDimLoc);

                this.InventDimId = inventDimLoc.inventDimId;
            }
        }
        return intercompanyTransferFulfillment;
    }

    /// <summary>
    /// Updates the replenishment Sales order reference on the corresponding Purchase order line.
    /// </summary>
    /// <remarks>
    /// This method attempts to find the matching <c>PurchLine</c> based on the replenishment PO reference
    /// stored on the Sales line. It ensures that the <c>ItemId</c> and inventory dimensions (site, warehouse,
    /// location) match between the Sales line and the Purchase line before updating the reference.
    /// Once the correct <c>PurchLine</c> is identified, the method updates its <c>METReplenishmentSOReference</c>
    /// field with the current Sales order ID, thereby establishing a cross-reference between the two documents.
    /// </remarks>
    public void updateIntercompanyPOReplenishmentReference()
    {
        PurchLine   purchLine;
        InventDim   salesInventDim = InventDim::find(this.InventDimId);
        InventDim   purchInventDim;
        SalesLine   salesLine = SalesLine::findRecId(this.RecId);

        if (salesLine.METReplenishmentPOReference)
        {
            changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
            {
                select firstonly forupdate METReplenishmentSOReference, RecId from purchLine
                    where purchLine.PurchId == salesLine.METReplenishmentPOReference
                    && purchLine.ItemId == salesLine.ItemId
                    && purchLine.PurchUnit == salesLine.SalesUnit;

                if (purchLine.RecId)
                {
                    ttsbegin;
                    purchLine.METReplenishmentSOReference = salesLine.SalesId;
                    // skip updating logic of puchrchase order header
                    using (var purchLineSkipBusinessLogicContext = PurchLineSkipBusinessLogicContext::construct())
                    {
                        purchLineSkipBusinessLogicContext.parmSkipUpdate(true);
                        purchLine.update();
                    }
                    ttscommit;
                }
            }

        }
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    /// <param name = "_dropInvent">_dropInvent</param>
    /// <param name = "_childBuffer">_childBuffer</param>
    /// <param name = "_updateOrderLineOfDeliverySchedule">_updateOrderLineOfDeliverySchedule</param>
    /// <param name = "_mcrAutoallocate">_mcrAutoallocate</param>
    /// <param name = "_cameFromCreate">_cameFromCreate</param>
    /// <param name = "_promptSuppItem">_promptSuppItem</param>
    public void update(boolean  _dropInvent,
                        Common   _childBuffer,
                        boolean  _updateOrderLineOfDeliverySchedule,
                        boolean  _mcrAutoallocate,
                        boolean  _cameFromCreate,
                        boolean  _promptSuppItem)
    {
        boolean         updateSalesUnitFields;
        METSalesLine    metSalesLineUpdate;
        SalesLine       salesLineOrig = this.orig();
        METSalesTable   metSalesTable = METSalesTable::findBySalesId(this.SalesId);
        METSalesLinePriceComponent metSalesLinePriceComponent;
        METSalesLinePriceComponentDetail metSalesLinePriceComponentDetail;
        NoYes           skipPriceCompDeletion = this.METSkipPriceCompDeletion;

        if (this.SalesUnit != salesLineOrig.SalesUnit ||  this.InventDimId != salesLineOrig.InventDimId)
        {
            updateSalesUnitFields = true;
        }

        if (this.METCWActualWeight != salesLineOrig.METCWActualWeight)
        {
            this.LineAmount = this.calcLineAmount(this.METCWActualWeight);
        }
        
        if (metSalesTable && (metSalesTable.OriginalSalesId || metSalesTable.ClaimSalesId))
        {
            this.metSetReturnUnitPriceAndDiscount(metSalesTable);
        }

        // Skip business events processing for this update operation
        METCheckSkipBusinessEventsHelper::shouldSkipBusinessEvents(this);

        next update(_dropInvent, _childBuffer, _updateOrderLineOfDeliverySchedule, _mcrAutoallocate, _cameFromCreate, _promptSuppItem);

        //CB274
        if (this.SalesQty != salesLineOrig.SalesQty)
        {
            InventDim salesInvetnDim = InventDim::find(this.InventDimId);
            this.updarePOReplenishmentLineDetails(salesInvetnDim);
        }
        //CB274

        metSalesLineUpdate = METSalesLine::find(this.RecId, true);

        // Avoid updating METSalesLine during data import - 317907 it will be directly updated through data entity
        RetailSalesOrderCreationContext context = RetailSalesOrderCreationContext::current();
        if (context == null || !context.parmDataImporting())
        {
            if (metSalesLineUpdate.RecId)
            {
                ttsbegin;
                // CB173 Sales Order Extract Screen V2 - refactor
                this.metSetActualUnitFields(metSalesLineUpdate);
                // CB871_CB872 Sales returns . Get unit in shipcase during return order line export
                this.metSetWMSFactor(metSalesLineUpdate);

                if (updateSalesUnitFields)
                {
                    metSalesLineUpdate = this.metSalesLine();
                    metSalesLineUpdate.selectForUpdate(true);
    
                    // CB173 Sales Order Extract Screen V2 - refactor
                    this.metSetSalesUnitFields(metSalesLineUpdate);
                    // CB871_CB872 Sales returns . Get unit in shipcase during return order line export
                    this.metSetWMSFactor(metSalesLineUpdate);

                    // Sales order Return / Claims
                    if (metSalesLineUpdate.salesLine().salesTable().SalesType == SalesType::ReturnItem)
                    {
                        this.metSetExciseDutyFields(metSalesLineUpdate);
                    }
                    // Sales order Return / Claims
                }
                ttscommit;

                this.metPackMETSalesLine(metSalesLineUpdate);
            }
            this.SysExtensionSerializerMap::postUpdate();
        }

        if (this.RemainSalesPhysical == 0 && this.RemainInventPhysical == 0)
        {
            metSalesLineUpdate = this.metSalesLine();
            metSalesLineUpdate.selectForUpdate(true);

            if (metSalesLineUpdate.OrderExtractStatus != METOrderExtractStatus::Extracted)
            {
                metSalesLineUpdate.updateExtractionStatus(METOrderExtractStatus::Extracted);
            }
        }
        // CB796 Send PE pricing purge value for custom tables
        if (!this.SalesPrice
            && salesLineOrig.SalesPrice
            && metSalesTable.OrderProcessingStatus != METSalesOrderProcessingStatus::PricingCompleted
            && skipPriceCompDeletion != NoYes::Yes)
        {
            // Purge the data in custom tables
            delete_from METSalesLinePriceComponent
                where METSalesLinePriceComponent.InventTransId == this.InventTransId;

            delete_from METSalesLinePriceComponentDetail
                where METSalesLinePriceComponentDetail.InventTransId == this.InventTransId;
        }

    }

    /// <summary>
    /// Update the Purch quantity based on related SO line.
    /// Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment) - Build (D365) - (SG) Part 6
    /// </summary>
    /// <param name = "_inventDim"></param>
    public void updarePOReplenishmentLineDetails(InventDim _inventDim)
    {
        InventDim   purchInventDim, salesInventDim;
        PurchLine   purchLine;
        SalesLine   salesLine = SalesLine::findRecId(this.RecId);

        changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
        {
            select firstonly forupdate PurchQty, RemainPurchPhysical, RemainInventPhysical, RecId, PurchId from purchLine
                where purchLine.PurchId == salesLine.METReplenishmentPOReference
                && purchLine.ItemId == salesLine.ItemId
                && purchLine.PurchUnit == salesLine.SalesUnit;

            if (purchLine.RecId)
            {
                ttsbegin;
                purchLine.PurchQty              = salesLine.SalesQty;
                purchLine.RemainPurchPhysical   = salesLine.SalesQty;
                purchLine.RemainInventPhysical  = salesLine.RemainInventPhysical;
                purchLine.update();
                ttscommit;

                //Confirm the PO after quantity is updated.
                METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchLine.PurchId);
            }
        }
    }

    /// <summary>
    /// Get InventTable buffer related to the SalesLine with limited fields
    /// </summary>
    /// <returns>InventTable buffer with limited fields</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public InventTable metInventTableLimitedFields()
    {
        InventTable     metInventTableLimitedFields;
        select firstonly Product, NetWeight, TaraWeight, UnitVolume
            from metInventTableLimitedFields
            where metInventTableLimitedFields.ItemId == this.ItemId;

        return metInventTableLimitedFields;
    }

