    private SalesUnit metWHSUnitId(InventDim _inventDim)
    {
        SalesUnit whsUnit;

        METExtWMSUnit whsUnitType = _inventDim.inventLocation().metInventLocation().ExternalWMSUnit;

        if (whsUnitType == METExtWMSUnit::DefaultSellUnit)
        {
            whsUnit = InventItemSalesSetup::find(this.ItemId, this.InventDimId).METSalesUnit;
        }
        else if (whsUnitType == METExtWMSUnit::DefaultPurchaseUnit)
        {
            whsUnit = InventItemPurchSetup::find(this.ItemId, this.InventDimId).METPurchUnit;
        }

        if (whsUnit == '' || whsUnittype == METExtWMSUnit::DefaultInventoryUnit)
        {
            whsUnit = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId;
        }

        return whsUnit;
    }

    private Factor metUnitConversionFactor(SalesUnit _toUnit)
    {
        Factor factor;

        factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        this.ItemId,
                        this.InventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.SalesUnit),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_toUnit),
                        NoYes::No,
                        NoYes::No);

        return factor;
    }

