    /// <summary>
    /// To get grossWeight for the SalesLine Item.
    /// </summary>
    /// <returns>GrossWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUnitGrossWeight displayMETUnitGrossWeight()
    {

        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
        WHSPhysDimUOM whsPhysDimUOM;
        Factor factor;
        InventDim inventDim = this.inventDim();
        Weight weight;

        SalesUnit whsUnit = this.metWHSUnitId(inventDim);

        //Find direct UOM weight
        select firstonly weight from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == this.ItemId
            && metWHSPhysDimUOMSite.UOM == whsUnit
            && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

        weight = metWHSPhysDimUOMSite.Weight;

        if(!weight)
        {
            select firstonly whsPhysDimUOM
                where whsPhysDimUOM.ItemId == this.ItemId
                && whsPhysDimUOM.UOM == whsUnit;

            weight = whsPhysDimUOM.Weight;
        }
        
        return weight;
    }

    /// <summary>
    /// Total gross weight
    /// </summary>
    /// <returns></returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUnitGrossWeight displayMETTotalGrossWeight()
    {

        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
        WHSPhysDimUOM whsPhysDimUOM;
        Factor factor;
        InventDim inventDim = this.inventDim();
        Weight weight;

        SalesUnit whsUnit = this.metWHSUnitId(inventDim);

        weight = this.displayMETUnitGrossWeight();
        
        factor = this.metUnitConversionFactor(whsUnit);

        
        return (this.SalesQty * factor) * weight;
    }

    /// <summary>
    /// To get grossWeight for the SalesLine Item.
    /// </summary>
    /// <returns>GrossWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUnitGrossVolume displayMETTotalGrossVolume()
    {

        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
        WHSPhysDimUOM whsPhysDimUOM;
        Factor factor;
        InventDim inventDim = this.inventDim();
        METUOMVolume volume;

        SalesUnit whsUnit = this.metWHSUnitId(inventDim);

        volume = this.displayMETUnitGrossVolume();
        
        factor = this.metUnitConversionFactor(whsUnit);

        return (this.SalesQty * volume) * factor;
    }

    /// <summary>
    /// To get unit gross volume for the SalesLine Item.
    /// </summary>
    /// <returns>GrossWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUnitGrossVolume displayMETUnitGrossVolume()
    {

        METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
        WHSPhysDimUOM whsPhysDimUOM;
        Factor factor;
        InventDim inventDim = this.inventDim();
        METUOMVolume volume;

        SalesUnit whsUnit = this.metWHSUnitId(inventDim);

        //Find direct UOM weight
        select firstonly metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == this.ItemId
            && metWHSPhysDimUOMSite.UOM == whsUnit
            && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

        volume = metWHSPhysDimUOMSite.displayCaseVolumeCM();

        if(!volume)
        {
            select firstonly whsPhysDimUOM
                where whsPhysDimUOM.ItemId == this.ItemId
                && whsPhysDimUOM.UOM == whsUnit;

            volume = whsPhysDimUOM.displayCaseVolumeCM();
        }
        
        return volume;
    }

