    /// <summary>
    /// To get actualWeight for the SalesLine Item.
    /// </summary>
    /// <returns>ActualWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METGrossWeight displayMETActualWeight()
    {
        // Cache frequently used values
        InventDim inventDim = this.inventDim();
        UnitOfMeasureSymbol unitSales = this.SalesUnit;
        UnitOfMeasureSymbol unitInvent = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId;
        METSalesLine metSalesLine = METSalesLine::find(this.RecId);

        // Prefer actual/captured weights if available
        if (this.METCWActualWeight != 0.0)
        {
            return this.METCWActualWeight;
        }
        if (metSalesLine.AISWeight != 0.0)
        {
            return metSalesLine.AISWeight;
        }

        // Cache actual case and broken case quantities
        InventQty actCase = this.displayMETActualCases();
        InventQty actBrokenCase = this.displayMETActualBrokenCase();

        // Calculate and return total actual weight
        METGrossWeight caseWeight = METWHSPhysDimUOMSite::convertWeight(this.ItemId, actCase, unitSales, inventDim);
        METGrossWeight brokenCaseWeight = METWHSPhysDimUOMSite::convertWeight(this.ItemId, actBrokenCase, unitInvent, inventDim);

        return caseWeight + brokenCaseWeight;
    }

