    /// <summary>
    /// SG-239135. Method to determine the Supplied quantity for the Sales Order confirmation for Food/G-Grocery Item in a liquor entity.
    /// </summary>
    /// <param name = "metLegalEntityType">An enum value for legal entity Food type or Liquor type</param>
    /// <returns>Boolean value, True if entity is of type Liquor and run for Order set with Intercompany transfer fulfillment and split group category of line, else false.</returns>
    public boolean determineSuppliedQtyForSOConfirmation(METLegalEntityType metLegalEntityType = METLegalEntityType::None)
    {
        boolean ret;
        METCustParameters metCustParameters = METCustParameters::Find();
       
        if (metLegalEntityType == METLegalEntityType::Liquor
            && metCustParameters
            && metCustParameters.OrderSplitGroupCodeSOSuppliedQty
            && this.salesTable().METIntercompanyTransferFulfillment == NoYes::Yes
            && metCustParameters.OrderSplitGroupCodeSOSuppliedQty == InventTable::metGetOSCCode(this.ItemId, this.inventDim()) )
        {
            ret = true;
        }

        return ret;
    }

    /// <summary>
    /// This method used for assiging values to MetSalesline.
    /// </summary>
    /// <param name = "_metSalesLine">METSalesLine</param>
    void metSetExciseDutyFields(METSalesLine _metSalesLine)
    {
        // Sales order Return / Claims
        METExciseInformationTable   exciseInformationTable;
        METExciseRegisterEntry      exciseRegisterEntry;
        METInventTable              metInventTable = METInventTable::find(this.ItemId);
        InventSiteId                inventSite     = this.inventDim().InventSiteId;

        if (metInventTable.METTariffItemCodeBaseRecid)
        {
            exciseInformationTable.clear();
            exciseRegisterEntry.clear();
            select firstonly Lodgement, RecId from exciseInformationTable order by CreatedDateTime asc
                where exciseInformationTable.ItemId == this.ItemId
                    && exciseInformationTable.SiteId == inventSite
                    && exciseInformationTable.LodgementClosed == NoYes::No
                join TIUV, Lodgement, DutyRateReceived, RecId from exciseRegisterEntry
                    where exciseRegisterEntry.Lodgement == exciseInformationTable.Lodgement;

            if (exciseInformationTable.RecId)
            {
                _metSalesLine.TIUV                      = exciseRegisterEntry.TIUV;
                _metSalesLine.Lodgement                 = exciseRegisterEntry.Lodgement;
                _metSalesLine.ValueOfDuty               = exciseRegisterEntry.DutyRateReceived;
                _metSalesLine.ContinuingPermissionNumber = SalesLine::findRecId(_metSalesLine.SalesLine).SalesId;
            }
            else
            {
                exciseInformationTable.clear();
                exciseRegisterEntry.clear();
                select firstonly Lodgement, RecId from exciseInformationTable order by ModifiedDateTime desc
                    where exciseInformationTable.ItemId == this.ItemId
                        && exciseInformationTable.SiteId == inventSite
                    join TIUV, Lodgement, DutyRateReceived, RecId from exciseRegisterEntry
                        where exciseRegisterEntry.Lodgement == exciseInformationTable.Lodgement;

                if (exciseInformationTable.RecId)
                {
                    _metSalesLine.TIUV                      = exciseRegisterEntry.TIUV;
                    _metSalesLine.Lodgement                 = exciseRegisterEntry.Lodgement;
                    _metSalesLine.ValueOfDuty               = exciseRegisterEntry.DutyRateReceived;
                    _metSalesLine.ContinuingPermissionNumber = _metSalesLine.salesLine().SalesId;
                }
            }
        }
        // Sales order Return / Claims
    }

    /// <summary>
    /// Bug 281545: CB515 - Not sending for repricing on Extraction
    /// </summary>
    public void metDeletePriceComponents()
    {
        METSalesLinePriceComponent          salesLinePriceComponent;
        METSalesLinePriceComponentDetail    salesLinePriceComponentDetail;
        
        ttsbegin;
        // delete price compoments records and component details
        delete_from salesLinePriceComponent
              where salesLinePriceComponent.InventTransId == this.InventTransId;

        delete_from salesLinePriceComponentDetail
              where salesLinePriceComponentDetail.InventTransId == this.InventTransId;
