    /// <summary>
    /// Get Sales Line Invoice Indicator
    /// </summary>
    /// <param name = "_addIndicator">Add Indicator</param>
    /// <returns>Indicator info</returns>
    public METInvIndicator getSalesLineInvoiceIndicator(boolean _addIndicator = false)
    {
        METSalesInvoiceIndicatorView salesInvoiceIndicator;
        container invoiceIndicator;
        str output;

        while select firstonly CimponentInvoiceIndicator from salesInvoiceIndicator
            where salesInvoiceIndicator.InventTransId == this.InventTransId
        {
            str invIndicator = enum2Str(salesInvoiceIndicator.CimponentInvoiceIndicator);

            if (!conFind(invoiceIndicator, invIndicator))
            {
                invoiceIndicator += invIndicator;
            }
        }

        if (_addIndicator)
        {
            METIndicators iomIndicator = this.metSalesLine().Indicators;

            if (iomIndicator)
            {
                if (!conFind(invoiceIndicator, iomIndicator))
                {
                    invoiceIndicator += iomIndicator;
                }
            }
        }

        if (conLen(invoiceIndicator) > 1)
        {
            output = con2Str(invoiceIndicator, ",");
        }
        else
        {
            output = con2Str(invoiceIndicator);
        }

        return output;
      
    }

    /// <summary>
    /// Display Picked Cases
    /// </summary>
    /// <returns>Picked cases</returns>
    public display METCase metDisplayPickedCases()
    {
        WMSOrderTrans wmsOrderTrans;

        select METPickedCases from wmsOrderTrans
            order by CreatedDateTime desc
            where wmsOrderTrans.InventTransId == this.InventTransId &&
                 wmsOrderTrans.expeditionStatus != WMSExpeditionStatus::Cancelled;

        return wmsOrderTrans.METPickedCases;
    }

    /// <summary>
    /// Display Picked Cases
    /// </summary>
    /// <returns>Picked broken cases</returns>
    public display METCase metDisplayPickedBrokenCases()
    {
        WMSOrderTrans wmsOrderTrans;

        select METPickedBrokenCases from wmsOrderTrans
            order by CreatedDateTime desc
            where wmsOrderTrans.InventTransId == this.InventTransId &&
                 wmsOrderTrans.expeditionStatus != WMSExpeditionStatus::Cancelled;

        return wmsOrderTrans.METPickedBrokenCases;
    }

    protected boolean mustUpdateSalesTable()
    {
        boolean ret;

        ret = next mustUpdateSalesTable();

        if (ret)
        {
            METSalesLineContext salesLineContext = METSalesLineContext::current();

            if (salesLineContext && salesLineContext.skipSalesTableUpdate == true)
            {
                ret = false;
            }
        }

        return ret;
    }

