    public container metReservedPhysicalInSalesInventUnit()
    {
        SalesQtyReservPhysical  salesQtyReservPhysicalInSalesUnit;
        SalesQtyReservPhysical  salesQtyReservPhysicalInInventUnit;

        salesQtyReservPhysicalInInventUnit = this.reservedPhysical();

        if (!salesQtyReservPhysicalInInventUnit)
        {
            return [0.00, 0.00];
        }

        UnitOfMeasureSymbol inventUnit = this.inventTable().inventUnitId();

        if (this.SalesUnit == inventUnit)
        {
            salesQtyReservPhysicalInSalesUnit = salesQtyReservPhysicalInInventUnit;
        }
        else
        {
            salesQtyReservPhysicalInSalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(this.ItemId,
                                                                                                                    this.InventDimId,
                                                                                                                    salesQtyReservPhysicalInInventUnit,
                                                                                                                    inventUnit,
                                                                                                                    this.SalesUnit,
                                                                                                                    NoYes::No);
        }

        return [salesQtyReservPhysicalInSalesUnit, salesQtyReservPhysicalInInventUnit];
    }
